mkdir -p /tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/oc && cat > /tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/oc/win.py <<'EOF'
import json, sys
# usage: win.py FILE START END [maxchars] [--tools]
path, start, end = sys.argv[1], sys.argv[2], sys.argv[3]
maxc = int(sys.argv[4]) if len(sys.argv) > 4 and sys.argv[4].isdigit() else 4000
tools = '--tools' in sys.argv
seen = set()
off = 0
with open(path, 'rb') as f:
    for n, raw in enumerate(f, 1):
        o = off; off += len(raw)
        i = raw.find(b'"timestamp":"')
        if i < 0: continue
        ts = raw[i+13:i+37].decode()
        if not (start <= ts < end): continue
        try: d = json.loads(raw)
        except Exception: continue
        if d.get('isSidechain'): continue
        u = d.get('uuid')
        if u in seen: continue
        seen.add(u)
        t = d.get('type')
        m = d.get('message') or {}
        c = m.get('content')
        if t == 'user':
            if isinstance(c, str):
                if c.startswith('This session is being continued'): continue
                print(f'=== L{n} off{o} {ts} USER{" meta" if d.get("isMeta") else ""} ({len(c)} ch)\n{c[:maxc]}\n')
            elif isinstance(c, list):
                for x in c:
                    if x.get('type') == 'text':
                        s = x['text']
                        print(f'=== L{n} off{o} {ts} USER-text{" meta" if d.get("isMeta") else ""} ({len(s)} ch)\n{s[:maxc]}\n')
                    elif x.get('type') == 'tool_result' and tools:
                        cc = x.get('content')
                        if isinstance(cc, list): cc = '\n'.join(y.get('text','') for y in cc if isinstance(y, dict))
                        cc = cc or ''
                        if 'Comment' in cc[:3000] or 'comment' in cc[:3000] or 'thread' in cc[:3000]:
                            print(f'=== L{n} off{o} {ts} TOOLRESULT ({len(cc)} ch)\n{cc[:maxc]}\n')
        elif t == 'assistant' and isinstance(c, list):
            for x in c:
                if x.get('type') == 'text' and x['text'].strip():
                    s = x['text']
                    print(f'=== L{n} off{o} {ts} ASSISTANT ({len(s)} ch)\n{s[:maxc]}\n')
                elif x.get('type') == 'tool_use' and tools and 'Artifact' in x.get('name',''):
                    print(f'=== L{n} off{o} {ts} TOOLUSE {x.get("name")} {json.dumps(x.get("input"))[:1500]}\n')
        elif t == 'queue-operation' or 'enqueue' in str(d.get('operation','')):
            print(f'=== L{n} off{o} {ts} QUEUE {json.dumps(d)[:maxc]}\n')
EOF
echo ok

